-- ================================================================================
-- DDL - Base de Datos y Definición de Tablas
-- ================================================================================
DROP DATABASE realtyflow_db;

-- BASE DE DATOS: REALTYFLOW_DB
CREATE DATABASE realtyflow_db;
USE realtyflow_db;

-- 1. CIUDAD
CREATE TABLE ciudad (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nombre VARCHAR(100) NOT NULL UNIQUE
);

-- 2. AGENTE
CREATE TABLE agente (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nombre VARCHAR(120) NOT NULL,
  telefono VARCHAR(20) NOT NULL,
  correo VARCHAR(200) NOT NULL UNIQUE,
  porcentaje_comision DECIMAL(5,2) DEFAULT 3.00 CHECK (porcentaje_comision >= 0),
  fecha_ingreso DATE,
  ciudad_id INT NOT NULL,
  FOREIGN KEY (ciudad_id) REFERENCES ciudad(id) ON DELETE RESTRICT
);

-- 3. CLIENTE
CREATE TABLE cliente (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nombre VARCHAR(120) NOT NULL,
  telefono VARCHAR(20) NOT NULL,
  correo VARCHAR(200) NOT NULL UNIQUE,
  tipo_publicacion_preferida ENUM('venta','alquiler'),
  tipo_inmueble_preferido ENUM('casa','apartamento','terreno'),
  ciudad_id INT NOT NULL,
  presupuesto_min DECIMAL(12,2) CHECK (presupuesto_min >= 0),
  presupuesto_max DECIMAL(12,2) CHECK (presupuesto_max >= 0),
  FOREIGN KEY (ciudad_id) REFERENCES ciudad(id) ON DELETE RESTRICT
);

-- 4. INMUEBLE
CREATE TABLE inmueble (
  id INT AUTO_INCREMENT PRIMARY KEY,
  tipo_publicacion ENUM('venta','alquiler') NOT NULL,
  tipo_inmueble ENUM('casa','apartamento','terreno') NOT NULL,
  direccion VARCHAR(200) NOT NULL,
  ciudad_id INT NOT NULL,
  area_m2 DECIMAL(10,2) NOT NULL CHECK (area_m2 > 0),
  habitaciones INT NOT NULL CHECK (habitaciones >= 0),
  banos INT NOT NULL CHECK (banos >= 0),
  anio_construccion INT NULL,
  estado ENUM('disponible','en_negociacion','vendida','alquilada') NOT NULL DEFAULT 'disponible',
  fecha_publicacion DATE,
  agente_exclusivo_id INT NULL,
  UNIQUE(direccion,ciudad_id),
  FOREIGN KEY (agente_exclusivo_id) REFERENCES agente(id) ON DELETE SET NULL,
  FOREIGN KEY (ciudad_id) REFERENCES ciudad(id) ON DELETE RESTRICT
);

-- 5. HISTORIAL DE PRECIOS
CREATE TABLE precio (
  id INT AUTO_INCREMENT PRIMARY KEY,
  inmueble_id INT NOT NULL,
  precio DECIMAL(14,2) NOT NULL CHECK (precio > 0),
  desde DATE NOT NULL,
  hasta DATE NULL,
  UNIQUE(inmueble_id, desde),
  FOREIGN KEY (inmueble_id) REFERENCES inmueble(id) ON DELETE CASCADE
);

-- 6. VISITA
CREATE TABLE visita (
    id INT AUTO_INCREMENT PRIMARY KEY,
    inmueble_id INT NOT NULL,
    cliente_id INT NOT NULL,
    agente_id INT NULL,
    fecha DATE NOT NULL,
    hora TIME NOT NULL,
    estado ENUM('programada','realizada','cancelada') DEFAULT 'programada' NOT NULL,
    notas TEXT,
    UNIQUE (inmueble_id, cliente_id, fecha, hora),
    FOREIGN KEY(inmueble_id) REFERENCES inmueble(id) ON DELETE CASCADE,
    FOREIGN KEY(cliente_id) REFERENCES cliente(id) ON DELETE CASCADE,
    FOREIGN KEY(agente_id) REFERENCES agente(id) ON DELETE SET NULL
);

-- 7. OFERTA
CREATE TABLE oferta (
    id INT AUTO_INCREMENT PRIMARY KEY,
    inmueble_id INT NOT NULL,
    cliente_id INT NOT NULL,
    fecha DATE NOT NULL,
    monto DECIMAL(14,2) NOT NULL CHECK (monto > 0),
    estado ENUM('pendiente','aceptada','rechazada') DEFAULT 'pendiente' NOT NULL,
    comentarios TEXT,
    UNIQUE (inmueble_id, cliente_id, monto),
    FOREIGN KEY(inmueble_id) REFERENCES inmueble(id) ON DELETE RESTRICT,
    FOREIGN KEY(cliente_id) REFERENCES cliente(id) ON DELETE CASCADE
);

-- 8. TRANSACCION
CREATE TABLE transaccion (
  id INT AUTO_INCREMENT PRIMARY KEY,
  inmueble_id INT NOT NULL,
  cliente_id INT NOT NULL,
  fecha_cierre DATE NOT NULL,
  precio_final DECIMAL(14,2) NOT NULL CHECK (precio_final > 0),
  tipo_transaccion ENUM('venta','alquiler') NOT NULL,
  estado_transaccion ENUM('cerrada','cancelada') DEFAULT 'cerrada' NOT NULL,
  oferta_id INT NULL,
  FOREIGN KEY(inmueble_id) REFERENCES inmueble(id) ON DELETE RESTRICT,
  FOREIGN KEY(cliente_id) REFERENCES cliente(id) ON DELETE RESTRICT,
  FOREIGN KEY(oferta_id) REFERENCES oferta(id) ON DELETE SET NULL
);

-- 9. TRANSACCION_AGENTE
CREATE TABLE transaccion_agente (
  transaccion_id INT NOT NULL,
  agente_id INT NOT NULL,
  comision_monto DECIMAL(14,2) CHECK (comision_monto >= 0),
  comision_porcentaje DECIMAL(5,2) NOT NULL CHECK (comision_porcentaje >= 0 AND comision_porcentaje <= 100),
  PRIMARY KEY(transaccion_id, agente_id),
  FOREIGN KEY(transaccion_id) REFERENCES transaccion(id) ON DELETE RESTRICT,
  FOREIGN KEY(agente_id) REFERENCES agente(id) ON DELETE RESTRICT
);

-- ================================================================================
-- MDL - DATOS
-- ================================================================================

-- ciudad: 10 registros

-- agente: 320 registros

-- cliente: 3,000 registros

-- inmueble: 2,000 registros

-- precio: 2,700 registros

-- visita: 3,500 registros

-- oferta: 5,500 registros

-- transaccion: 2,012 registros

-- transaccion_agente: 2,403 registros

--FIN

SELECT realtyflow_db.transaccion_agente.agente_id from transaccion_agente;